-- ORBITA SETUP — paste this whole file into Supabase > SQL Editor and click Run.
-- It deletes the old PK Online articles table, creates the new posts table + photo storage, and loads starter news.

-- Orbita: replaces the old PK Online `articles` table with `posts`,
-- adds a public `media` bucket for photo uploads, and staff permissions.
-- Keeps: public.profiles, private.has_cms_role(), the new-user trigger.

drop table if exists public.articles cascade;

create table public.posts (
  id uuid primary key default gen_random_uuid(),
  title text not null default '',
  slug text not null unique,
  excerpt text not null default '',
  body text not null default '',
  category text not null default 'kosova' check (category in ('kosova','politike','ekonomi','bota','sport','teknologji','kulture')),
  cover_url text,
  cover_alt text,
  featured boolean not null default false,
  status text not null default 'draft' check (status in ('draft','review','published')),
  author_id uuid default auth.uid() references auth.users(id) on delete set null,
  author_name text,
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index posts_published_idx on public.posts (status, published_at desc);
create index posts_category_idx on public.posts (category, published_at desc);
create index posts_author_idx on public.posts (author_id);
create trigger posts_touch_updated_at before update on public.posts for each row execute function public.touch_updated_at();

alter table public.posts enable row level security;

create policy "Anyone reads published posts" on public.posts for select to anon, authenticated
  using (status = 'published');
create policy "Staff read own or all posts" on public.posts for select to authenticated
  using ((select private.has_cms_role(array['admin','manager'])) or author_id = (select auth.uid()));
create policy "Staff create posts" on public.posts for insert to authenticated
  with check (author_id = (select auth.uid()) and (
    (select private.has_cms_role(array['admin','manager']))
    or ((select private.has_cms_role(array['editor'])) and status in ('draft','review'))));
create policy "Staff update posts" on public.posts for update to authenticated
  using ((select private.has_cms_role(array['admin','manager']))
    or (author_id = (select auth.uid()) and status in ('draft','review') and (select private.has_cms_role(array['editor']))))
  with check ((select private.has_cms_role(array['admin','manager']))
    or (author_id = (select auth.uid()) and status in ('draft','review') and (select private.has_cms_role(array['editor']))));
create policy "Staff delete posts" on public.posts for delete to authenticated
  using ((select private.has_cms_role(array['admin','manager'])) or (author_id = (select auth.uid()) and status <> 'published'));

create policy "Staff can read team profiles" on public.profiles for select to authenticated
  using ((select private.has_cms_role(array['admin','manager','editor'])));

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('media','media', true, 10485760, array['image/jpeg','image/png','image/webp','image/gif','image/avif'])
on conflict (id) do nothing;

create policy "Staff upload media" on storage.objects for insert to authenticated
  with check (bucket_id = 'media' and (select private.has_cms_role(array['admin','manager','editor'])));
create policy "Staff update media" on storage.objects for update to authenticated
  using (bucket_id = 'media' and (select private.has_cms_role(array['admin','manager','editor'])));
create policy "Managers delete media" on storage.objects for delete to authenticated
  using (bucket_id = 'media' and (select private.has_cms_role(array['admin','manager'])));


-- Starter news posts (short original write-ups, source credited and linked)
insert into public.posts (title, slug, excerpt, body, category, cover_url, cover_alt, featured, status, author_id, author_name, published_at) values
($q$Policia rrethon QKMF-në në Fushë Kosovë pas dyshimeve për mjet shpërthyes$q$, $q$policia-rrethon-qkmf-ne-fushe-kosove$q$, $q$Zona rreth Qendrës Kryesore të Mjekësisë Familjare në Fushë Kosovë është izoluar nga policia, pas dyshimeve se aty ndodhet një mjet shpërthyes.$q$, $q$<p>Policia e Kosovës ka rrethuar zonën përreth Qendrës Kryesore të Mjekësisë Familjare (QKMF) në Fushë Kosovë, pas dyshimeve për praninë e një mjeti shpërthyes, raporton Indeksonline.</p><p>Detaje të mëtejshme për rastin pritet të bëhen të ditura nga Policia. Qytetarët këshillohen ta shmangin zonën dhe t’i ndjekin udhëzimet e zyrtarëve në terren.</p><p>Orbita do ta përditësojë këtë lajm sapo të ketë informacione të reja.</p><p><em>Burimi: <a href="https://indeksonline.net/dyshime-per-mjet-shperthyes-ne-qkmf-ne-e-fushe-kosoves-policia-rrethon-zonen/">Indeksonline</a></em></p>$q$, $q$kosova$q$, $q$https://images.unsplash.com/photo-1551836022-d5d88e9218df?auto=format&fit=crop&w=1400&q=80$q$, $q$Foto ilustruese$q$, true, 'published', null, 'Redaksia Orbita', now() - interval '35 minutes'),
($q$Rotacion i ri i ushtrisë amerikane në Kosovë, zëvendësohet njësia e Gardës Kombëtare$q$, $q$rotacion-i-ri-ushtria-amerikane-ne-kosove$q$, $q$Në Kosovë po ndodh një ndërrim i ri i trupave amerikane, ku njësia e Gardës Kombëtare zëvendësohet me një kontingjent të ri.$q$, $q$<p>Ushtria amerikane po kryen një lëvizje të re në Kosovë, ku njësia e Gardës Kombëtare që ka shërbyer deri tani zëvendësohet, sipas raportimit të Indeksonline.</p><p>Trupat amerikane në Kosovë shërbejnë në kuadër të misionit paqeruajtës të NATO-s, KFOR, dhe ndërrimet e njësive bëhen rregullisht si pjesë e këtij misioni.</p><p><em>Burimi: <a href="https://indeksonline.net/levizje-e-re-e-ushtrise-amerikane-ne-kosove-zevendesohet-garda-kombetare/">Indeksonline</a></em></p>$q$, $q$kosova$q$, $q$https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=1400&q=80$q$, $q$Foto ilustruese$q$, false, 'published', null, 'Redaksia Orbita', now() - interval '70 minutes'),
($q$Arrestohet një zyrtar i Komunës së Prishtinës për ryshfet dhe keqpërdorim të detyrës$q$, $q$arrestohet-zyrtar-komuna-prishtines-ryshfet$q$, $q$Një zyrtar i Komunës së Prishtinës është arrestuar nën dyshimin për marrje ryshfeti dhe keqpërdorim të detyrës zyrtare.$q$, $q$<p>Një zyrtar i Komunës së Prishtinës është arrestuar i dyshuar për marrje ryshfeti dhe keqpërdorim të pozitës zyrtare, raporton Indeksonline.</p><p>Rasti është në fazën e hetimeve. I dyshuari gëzon prezumimin e pafajësisë derisa fajësia e tij të vërtetohet me vendim të formës së prerë.</p><p><em>Burimi: <a href="https://indeksonline.net/ky-eshte-zyrtari-i-komunes-se-prishtines-qe-u-arrestua-per-ryshfet-dhe-keqperdorim-te-detyres/">Indeksonline</a></em></p>$q$, $q$kosova$q$, $q$https://images.unsplash.com/photo-1450101499163-c8848c66ca85?auto=format&fit=crop&w=1400&q=80$q$, $q$Foto ilustruese$q$, false, 'published', null, 'Redaksia Orbita', now() - interval '95 minutes'),
($q$Një pjesë e madhe e Prishtinës mbetet pa ujë, riparimi pritet për dy deri në tre orë$q$, $q$pjese-e-madhe-e-prishtines-pa-uje$q$, $q$Furnizimi me ujë është ndërprerë në një pjesë të madhe të kryeqytetit, ndërsa sanimi i defektit pritet të zgjasë dy deri në tre orë.$q$, $q$<p>Shumë lagje të Prishtinës kanë mbetur pa ujë, raporton Indeksonline. Sipas deklaratave të cituara nga portali, sanimi pritet të përfundojë brenda dy deri në tre orësh.</p><p>Qytetarët këshillohen të kursejnë rezervat e ujit derisa furnizimi të rikthehet plotësisht.</p><p><em>Burimi: <a href="https://indeksonline.net/nje-pjese-e-madhe-e-prishtines-pa-uje-mjeku-sanimi-pritet-te-behet-per-2-a-3-ore/">Indeksonline</a></em></p>$q$, $q$kosova$q$, $q$https://images.unsplash.com/photo-1518005020951-eccb494ad742?auto=format&fit=crop&w=1400&q=80$q$, $q$Foto ilustruese$q$, false, 'published', null, 'Redaksia Orbita', now() - interval '130 minutes'),
($q$Policia gjen armë dhe municion në dy fshatra të Zubin Potokut$q$, $q$arme-municion-zubin-potok$q$, $q$Gjatë një operacioni në dy fshatra të Zubin Potokut, Policia e Kosovës ka gjetur armë dhe municion.$q$, $q$<p>Policia e Kosovës ka gjetur armë dhe municion në dy fshatra të komunës së Zubin Potokut, raporton Indeksonline.</p><p>Armët dhe municioni i gjetur pritet t’u nënshtrohen procedurave të zakonshme hetimore.</p><p><em>Burimi: <a href="https://indeksonline.net/policia-gjen-arme-e-municion-ne-dy-fshatra-te-zubin-potokut/">Indeksonline</a></em></p>$q$, $q$kosova$q$, null, null, false, 'published', null, 'Redaksia Orbita', now() - interval '180 minutes'),
($q$203 raste me fruth nga prilli deri në tetor, IKShPK: vaksinimi mbetet mbrojtja më e mirë$q$, $q$fruthi-203-raste-prill-tetor$q$, $q$Instituti Kombëtar i Shëndetësisë Publike ka regjistruar 203 raste me fruth në periudhën prill–tetor dhe u bën thirrje prindërve të vaksinojnë fëmijët.$q$, $q$<p>Në periudhën prill–tetor në Kosovë janë regjistruar 203 raste me fruth, sipas Institutit Kombëtar të Shëndetësisë Publike të Kosovës (IKShPK), raporton Telegrafi.</p><p>IKShPK thekson se vaksinimi mbetet masa më efikase për mbrojtjen e shëndetit të fëmijëve dhe u bën thirrje prindërve që t’i kontrollojnë dhe plotësojnë dozat e vaksinave.</p><p>Fruthi është sëmundje shumë ngjitëse që përhapet përmes ajrit, dhe vaksina MMR jepet në dy doza.</p><p><em>Burimi: <a href="https://telegrafi.com/ne-periudhen-prill-tetor-203-raste-me-fruth-ikshpk-vaksinimi-masa-me-efikase-per-shendetin-e-femijeve/">Telegrafi</a></em></p>$q$, $q$kosova$q$, $q$https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?auto=format&fit=crop&w=1400&q=80$q$, $q$Foto ilustruese$q$, false, 'published', null, 'Redaksia Orbita', now() - interval '240 minutes'),
($q$Studentja e parë amerikane nis studimet e rregullta në Fakultetin Juridik të UP-së$q$, $q$studentja-e-pare-amerikane-juridiku-up$q$, $q$Një studente nga Shtetet e Bashkuara është regjistruar si studente e rregullt në Fakultetin Juridik të Universitetit të Prishtinës, e para e këtij lloji.$q$, $q$<p>Fakulteti Juridik i Universitetit të Prishtinës ka mirëpritur studenten e parë amerikane që nis studimet e rregullta në këtë fakultet, raporton Indeksonline.</p><p>Rasti shihet si shenjë e interesimit në rritje të studentëve të huaj për programet akademike në Kosovë.</p><p><em>Burimi: <a href="https://indeksonline.net/studentja-e-pare-amerikane-nis-studimet-e-rregullta-ne-fakultetin-juridik-te-up-se/">Indeksonline</a></em></p>$q$, $q$kosova$q$, null, null, false, 'published', null, 'Redaksia Orbita', now() - interval '300 minutes'),
($q$Ariu që ngeci në gjemba në Junik shpëtohet nga banorët$q$, $q$ariu-junik-shpetohet-nga-banoret$q$, $q$Një ari që kishte ngecur në gjemba në Junik është shpëtuar falë ndërhyrjes së banorëve të zonës.$q$, $q$<p>Banorët e Junikut kanë ndihmuar në shpëtimin e një ariu që kishte mbetur i ngecur në gjemba, raporton Indeksonline, e cila ka publikuar edhe pamje nga ngjarja.</p><p>Zona malore e Junikut, pranë Bjeshkëve të Nemuna, njihet si habitat i ariut të murrmë.</p><p><em>Burimi: <a href="https://indeksonline.net/ariu-mbeti-ne-gjemba-ne-junik-shpetohet-nga-komuniteti-pamje/">Indeksonline</a></em></p>$q$, $q$kosova$q$, null, null, false, 'published', null, 'Redaksia Orbita', now() - interval '420 minutes'),
($q$Presidentja Shiroka-Pula takon familjet e ish-krerëve të UÇK-së: Do të veprojmë në mbështetje të drejtësisë$q$, $q$shiroka-pula-takon-familjet-ish-kreret-uck$q$, $q$Presidentja e Kosovës, Justina Shiroka-Pula, është takuar me familjet e ish-krerëve të UÇK-së dhe ka premtuar mbështetje për përpjekjet e tyre për drejtësi.$q$, $q$<p>Presidentja e Kosovës, Justina Shiroka-Pula, ka pritur në takim familjet e ish-krerëve të Ushtrisë Çlirimtare të Kosovës, që përballen me procesin gjyqësor në Hagë, raporton Indeksonline.</p><p>Pas takimit, Presidentja deklaroi se do të veprojë në mbështetje të përpjekjeve për drejtësi.</p><p>Takimi vjen pak ditë pasi Shiroka-Pula u zgjodh presidente nga Kuvendi i Kosovës.</p><p><em>Burimi: <a href="https://indeksonline.net/shiroka-pula-takon-familjet-e-ish-krereve-te-uck-se-do-te-veprojme-ne-mbeshtetje-te-perpjekjeve-per-drejtesi/">Indeksonline</a></em></p>$q$, $q$politike$q$, $q$https://images.unsplash.com/photo-1529107386315-e1a2ed48a620?auto=format&fit=crop&w=1400&q=80$q$, $q$Foto ilustruese$q$, false, 'published', null, 'Redaksia Orbita', now() - interval '50 minutes'),
($q$Ndryshimet në Ligjin për parandalimin e pastrimit të parave kalojnë në komisionin parlamentar$q$, $q$ligji-pastrimi-parave-kalon-ne-komision$q$, $q$Plotësim-ndryshimet e Ligjit për parandalimin e pastrimit të parave kanë marrë miratimin në komisionin përkatës të Kuvendit.$q$, $q$<p>Ndryshimet në Ligjin për parandalimin e pastrimit të parave dhe financimit të terrorizmit kanë kaluar në komisionin përkatës parlamentar, raporton Indeksonline.</p><p>Pas shqyrtimit në komision, projektligji pritet të procedohet për shqyrtim në seancë plenare të Kuvendit.</p><p><em>Burimi: <a href="https://indeksonline.net/kalojne-ne-komision-ndryshimet-ne-ligjin-per-parandalimin-e-pastrimit-te-parave/">Indeksonline</a></em></p>$q$, $q$politike$q$, $q$https://images.unsplash.com/photo-1523995462485-3d171b5c8fa9?auto=format&fit=crop&w=1400&q=80$q$, $q$Foto ilustruese$q$, false, 'published', null, 'Redaksia Orbita', now() - interval '200 minutes'),
($q$Protesta në Tiranë: 13 të lënduar, mes tyre protestues, policë, gazetarë dhe kalimtarë$q$, $q$protesta-tirane-13-te-lenduar$q$, $q$Një protestë në Tiranë është përshkallëzuar, duke lënë të lënduar 13 persona, mes tyre protestues, efektivë policie, gazetarë dhe kalimtarë.$q$, $q$<p>Trembëdhjetë persona janë lënduar gjatë një proteste në Tiranë, raporton Indeksonline. Mes të lënduarve ka protestues, policë, gazetarë dhe qytetarë që ndodheshin rastësisht në zonë.</p><p>Orbita do të sjellë detaje të reja për rrethanat dhe gjendjen e të lënduarve sapo të bëhen publike.</p><p><em>Burimi: <a href="https://indeksonline.net/protesta-ne-tirane-13-te-lenduar-mes-tyre-protestues-police-gazetare-dhe-kalimtare/">Indeksonline</a></em></p>$q$, $q$bota$q$, $q$https://images.unsplash.com/photo-1489493585363-d69421e0edd3?auto=format&fit=crop&w=1400&q=80$q$, $q$Foto ilustruese$q$, false, 'published', null, 'Redaksia Orbita', now() - interval '80 minutes'),
($q$BE miraton paketën më të madhe të sanksioneve ndaj Rusisë, në shënjestër industria e raketave balistike$q$, $q$be-sanksionet-me-te-medha-ndaj-rusise$q$, $q$Bashkimi Evropian ka miratuar paketën më të gjerë të sanksioneve ndaj Rusisë deri më sot, duke goditur industrinë e raketave balistike.$q$, $q$<p>Bashkimi Evropian ka miratuar atë që përshkruhet si paketa më e madhe e sanksioneve ndaj Rusisë, raporton Indeksonline. Masat e reja synojnë drejtpërdrejt industrinë ruse të raketave balistike.</p><p>BE-ja ka miratuar paketa të njëpasnjëshme sanksionesh ndaj Moskës që nga pushtimi i plotë i Ukrainës në shkurt të vitit 2022.</p><p><em>Burimi: <a href="https://indeksonline.net/">Indeksonline</a></em></p>$q$, $q$bota$q$, $q$https://images.unsplash.com/photo-1521295121783-8a321d551ad2?auto=format&fit=crop&w=1400&q=80$q$, $q$Foto ilustruese$q$, false, 'published', null, 'Redaksia Orbita', now() - interval '150 minutes'),
($q$Sulme me dronë në Detin e Zi, fundoset një anije tregtare pranë Bullgarisë$q$, $q$deti-i-zi-dronet-fundoset-anija-bullgari$q$, $q$Një anije tregtare është fundosur pranë brigjeve të Bullgarisë, në mes të sulmeve me dronë në Detin e Zi.$q$, $q$<p>Një anije tregtare është fundosur pranë Bullgarisë, në kontekstin e sulmeve me dronë në Detin e Zi, raporton Indeksonline.</p><p>Deti i Zi mbetet zonë e tensionuar për transportin detar që nga fillimi i luftës në Ukrainë.</p><p><em>Burimi: <a href="https://indeksonline.net/">Indeksonline</a></em></p>$q$, $q$bota$q$, $q$https://images.unsplash.com/photo-1500375592092-40eb2168fd21?auto=format&fit=crop&w=1400&q=80$q$, $q$Foto ilustruese$q$, false, 'published', null, 'Redaksia Orbita', now() - interval '260 minutes'),
($q$Komandanti i NATO-s paralajmëron Rusinë: Aleanca është e gatshme të fitojë në rast sulmi$q$, $q$komandanti-nato-paralajmeron-rusine$q$, $q$Komandanti i NATO-s ka deklaruar se Aleanca është e përgatitur dhe e gatshme të fitojë nëse sulmohet.$q$, $q$<p>Komandanti i NATO-s i ka dërguar një paralajmërim Rusisë, duke deklaruar se Aleanca Veriatlantike është e gatshme të fitojë në rast sulmi, raporton Indeksonline.</p><p>Deklarata vjen në një periudhë tensionesh të rritura ndërmjet NATO-s dhe Moskës.</p><p><em>Burimi: <a href="https://indeksonline.net/">Indeksonline</a></em></p>$q$, $q$bota$q$, null, null, false, 'published', null, 'Redaksia Orbita', now() - interval '360 minutes'),
($q$Gjilani i kthehet fitoreve, mposht bindshëm Drenicën$q$, $q$gjilani-mposht-drenicen$q$, $q$Gjilani ka rikthyer buzëqeshjen pas një fitoreje bindëse ndaj Drenicës në Superligën e Kosovës.$q$, $q$<p>SC Gjilani është rikthyer te fitoret, pasi mposhti bindshëm Drenicën, raporton Indeksonline.</p><p>Me këtë fitore, Gjilani merr tre pikë të rëndësishme në garën e Superligës së Kosovës.</p><p><em>Burimi: <a href="https://indeksonline.net/gjilani-i-kthehet-fitoreve-mposht-bindshem-drenicen/">Indeksonline</a></em></p>$q$, $q$sport$q$, $q$https://images.unsplash.com/photo-1574629810360-7efbbe195018?auto=format&fit=crop&w=1400&q=80$q$, $q$Foto ilustruese$q$, false, 'published', null, 'Redaksia Orbita', now() - interval '110 minutes'),
($q$Kosova në Vjenë, Shqipëria ndaj Uellsit: publikohen formacionet e kombëtareve$q$, $q$kombetaret-kosova-austria-shqiperia-uellsi$q$, $q$Përzgjedhësit e Kosovës dhe Shqipërisë kanë zbuluar formacionet për ndeshjet ndaj Austrisë në Vjenë dhe ndaj Uellsit.$q$, $q$<p>Kosova ka publikuar formacionin për ndeshjen ndaj Austrisë në Vjenë, ndërsa Kombëtarja Shqiptare ka zbuluar formacionin me të cilin synon përmbysjen ndaj Uellsit, raporton Indeksonline.</p><p>Të dyja kombëtaret shqiptare luajnë në të njëjtin xhiro të ndeshjeve ndërkombëtare.</p><p><em>Burimi: <a href="https://indeksonline.net/kombetarja-shqiptare-tenton-permbysjen-ndaj-uellsit-publikohen-formacionet/">Indeksonline</a></em></p>$q$, $q$sport$q$, $q$https://images.unsplash.com/photo-1522778119026-d647f0596c20?auto=format&fit=crop&w=1400&q=80$q$, $q$Foto ilustruese$q$, false, 'published', null, 'Redaksia Orbita', now() - interval '320 minutes'),
($q$BALFIN Group dhe Flying Tiger Copenhagen zgjerojnë partneritetin në tre tregje të BE-së$q$, $q$balfin-flying-tiger-zgjerim-be$q$, $q$Grupi BALFIN dhe rrjeti danez i dyqaneve Flying Tiger Copenhagen kanë zgjeruar bashkëpunimin në tre tregje të reja të Bashkimit Evropian.$q$, $q$<p>BALFIN Group, një nga grupet më të mëdha investuese në rajon, dhe Flying Tiger Copenhagen kanë njoftuar zgjerimin e partneritetit të tyre në tre tregje të Bashkimit Evropian, raporton Indeksonline.</p><p>Flying Tiger Copenhagen është rrjet danez i dyqaneve me produkte për shtëpinë, dhuratat dhe lodrat.</p><p><em>Burimi: <a href="https://indeksonline.net/">Indeksonline</a></em></p>$q$, $q$ekonomi$q$, $q$https://images.unsplash.com/photo-1554224155-6726b3ff858f?auto=format&fit=crop&w=1400&q=80$q$, $q$Foto ilustruese$q$, false, 'published', null, 'Redaksia Orbita', now() - interval '280 minutes'),
($q$Gati gjysma e kosovarëve përdorin ChatGPT, 73% e pyetjeve janë private$q$, $q$gjysma-e-kosovareve-perdorin-chatgpt$q$, $q$Gati gjysma e qytetarëve të Kosovës përdorin ChatGPT, ndërsa shumica e pyetjeve që i bëjnë kanë natyrë private.$q$, $q$<p>Gati gjysma e kosovarëve përdorin ChatGPT, ndërsa 73 për qind e pyetjeve të tyre kanë karakter privat, raporton Indeksonline.</p><p>Të dhënat tregojnë se mjetet e inteligjencës artificiale po përdoren gjithnjë e më shumë edhe për çështje personale, jo vetëm për punë ose shkollë.</p><p><em>Burimi: <a href="https://indeksonline.net/">Indeksonline</a></em></p>$q$, $q$teknologji$q$, $q$https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=1400&q=80$q$, $q$Foto ilustruese$q$, false, 'published', null, 'Redaksia Orbita', now() - interval '230 minutes'),
($q$IKShPK: Nuk ka konfirmim për variantin “Stratus” të COVID-19 në Kosovë$q$, $q$ikshpk-variant-stratus-covid$q$, $q$Instituti Kombëtar i Shëndetësisë Publike thotë se nuk ka konfirmim për praninë e variantit “Stratus” të COVID-19 në Kosovë.$q$, $q$<p>Në Kosovë nuk ka konfirmim për praninë e variantit “Stratus” të COVID-19, raporton Indeksonline, duke iu referuar institucioneve shëndetësore.</p><p>Institucionet shëndetësore vazhdojnë monitorimin e situatës epidemiologjike në vend.</p><p><em>Burimi: <a href="https://indeksonline.net/">Indeksonline</a></em></p>$q$, $q$kosova$q$, null, null, false, 'published', null, 'Redaksia Orbita', now() - interval '500 minutes'),
($q$Poetja Anne Carson fiton çmimin Nobel për letërsi$q$, $q$anne-carson-fiton-nobelin-per-leteresi$q$, $q$Poetja dhe eseistja kanadeze Anne Carson është fituesja e çmimit Nobel për letërsi.$q$, $q$<p>Anne Carson, poete, eseiste dhe përkthyese nga Kanadaja, është shpallur fituese e çmimit Nobel për letërsi, raporton Indeksonline.</p><p>Carson njihet për veprat që ndërthurin poezinë, esenë dhe letërsinë klasike, mes tyre “Autobiography of Red”, si dhe për përkthimet e saj nga greqishtja e lashtë.</p><p><em>Burimi: <a href="https://indeksonline.net/poetja-anne-carson-fiton-cmimin-nobel-per-letersi/">Indeksonline</a></em></p>$q$, $q$kulture$q$, null, null, false, 'published', null, 'Redaksia Orbita', now() - interval '400 minutes');
